import json
import os
import re

import psycopg2
from sqlglot import exp, parse

from bedrock_client import invoke_claude


SCHEMA_CONTEXT = """
Available PostgreSQL tables:
clients(id, name, industry, region, contract_value, created_date)
projects(id, client_id, name, status, start_date, end_date, budget)
consultants(id, name, grade, specialisation, project_id, billable_hours)
invoices(id, project_id, amount, status, due_date, paid_date)

Project status values: active, completed, on-hold.
All monetary values are USD.
"""

ALLOWED_TABLES = {"clients", "projects", "consultants", "invoices"}
UNSAFE_WORDS = re.compile(
    r"\b(DROP|DELETE|UPDATE|INSERT|ALTER|TRUNCATE|EXEC|EXECUTE|"
    r"GRANT|REVOKE|CREATE|MERGE|CALL|COPY|VACUUM|DO)\b",
    re.IGNORECASE,
)
DANGEROUS_FUNCTIONS = re.compile(
    r"\b(pg_sleep|dblink|lo_import|lo_export)\s*\(",
    re.IGNORECASE,
)
UNSAFE_REQUESTS = re.compile(
    r"\b(DROP|DELETE|UPDATE|INSERT|ALTER|TRUNCATE|"
    r"DESTROY|MODIFY|REMOVE)\b",
    re.IGNORECASE,
)
MAX_ROWS = int(os.getenv("SQL_MAX_ROWS", "1000"))
STATEMENT_TIMEOUT_MS = int(os.getenv("SQL_STATEMENT_TIMEOUT_MS", "10000"))
CONNECT_TIMEOUT_SECONDS = int(os.getenv("RDS_CONNECT_TIMEOUT", "5"))

def generate_sql(
    question: str,
    trace_id: str | None = None,
) -> tuple[str, dict]:
    prompt = (
        f"{SCHEMA_CONTEXT}\n\n"
        f"Generate one concise read-only SQL query for: {question}\n"
        "Return only one PostgreSQL SELECT query. "
        "Do not use comments, multiple statements, writes, locks, or unauthorized tables. "
        "Keep the query under 20 lines. "
        "For active-project risk questions, prioritize project status, dates, "
        "budget, invoice status, and consultant allocation. "
        "Avoid unnecessary metrics and overly complex calculations."
    )

    result = invoke_claude(
        prompt,
        max_tokens=1024,
        stage="sql_generation",
        question=question,
        trace_id=trace_id,
    )

    sql = re.sub(
        r"^\s*```(?:sql)?\s*|\s*```\s*$",
        "",
        result["text"],
        flags=re.IGNORECASE,
    ).strip()

    return sql, {
        "input": result["input_tokens"],
        "output": result["output_tokens"],
    }


def _mask_string_literals(query: str) -> str:
    return re.sub(r"'(?:''|[^'])*'", "''", query)


def validate_sql(query: str) -> dict:
    if not query or not query.strip():
        return {"valid": False, "reason": "Empty SQL query."}

    if "\x00" in query:
        return {"valid": False, "reason": "Null bytes are not permitted."}

    if re.search(r"--|/\*|\*/|#", query):
        return {"valid": False, "reason": "SQL comments are not permitted."}

    stripped = query.strip()
    without_terminal_semicolon = stripped[:-1].rstrip() if stripped.endswith(";") else stripped

    if ";" in without_terminal_semicolon:
        return {"valid": False, "reason": "Multiple SQL statements are not permitted."}

    masked = _mask_string_literals(without_terminal_semicolon)

    if UNSAFE_WORDS.search(masked):
        return {"valid": False, "reason": "Unsafe SQL keyword detected."}

    if DANGEROUS_FUNCTIONS.search(masked):
        return {"valid": False, "reason": "Potentially dangerous SQL function detected."}

    if re.search(r"\bSELECT\s+INTO\b|\bFOR\s+(UPDATE|NO\s+KEY\s+UPDATE|SHARE)\b", masked, re.I):
        return {"valid": False, "reason": "Write or locking clauses are not permitted."}

    if not re.match(r"^(SELECT|WITH)\b", without_terminal_semicolon, re.I):
        return {"valid": False, "reason": "Only SELECT or read-only WITH queries are permitted."}

    try:
        statements = parse(without_terminal_semicolon, read="postgres")
    except Exception as exc:
        return {"valid": False, "reason": f"SQL parser rejected the query: {exc}"}

    if len(statements) != 1:
        return {"valid": False, "reason": "Exactly one SQL statement is required."}

    tree = statements[0]
    if not isinstance(tree, (exp.Select, exp.Union)):
        return {"valid": False, "reason": "Only SELECT expressions are permitted."}

    cte_names = {
        cte.alias_or_name.lower()
        for cte in tree.find_all(exp.CTE)
        if cte.alias_or_name
    }

    for table in tree.find_all(exp.Table):
        table_name = table.name.lower()
        if table_name not in ALLOWED_TABLES and table_name not in cte_names:
            return {
                "valid": False,
                "reason": f"Table '{table_name}' is not on the approved allowlist.",
            }

    return {"valid": True, "reason": "OK"}


def execute_query_safely(sql: str) -> dict:
    validation = validate_sql(sql)
    if not validation["valid"]:
        return {
            "success": False,
            "error": validation["reason"],
            "validation": "BLOCKED",
        }

    conn = None
    try:
        conn = psycopg2.connect(
            host=os.environ["RDS_HOST"],
            port=int(os.getenv("RDS_PORT", "5432")),
            dbname=os.environ["RDS_DATABASE"],
            user=os.environ["RDS_USER"],
            password=os.environ["RDS_PASSWORD"],
            connect_timeout=CONNECT_TIMEOUT_SECONDS,
        )
        conn.set_session(readonly=True, autocommit=False)

        with conn.cursor() as cursor:
            cursor.execute("SET LOCAL statement_timeout = %s", (f"{STATEMENT_TIMEOUT_MS}ms",))
            cursor.execute("SET LOCAL lock_timeout = %s", (f"{STATEMENT_TIMEOUT_MS}ms",))
            cursor.execute(sql)

            columns = [description[0] for description in cursor.description or []]
            rows = cursor.fetchmany(MAX_ROWS + 1)
            truncated = len(rows) > MAX_ROWS

        conn.rollback()
        return {
            "success": True,
            "columns": columns,
            "rows": rows[:MAX_ROWS],
            "row_count": min(len(rows), MAX_ROWS),
            "truncated": truncated,
            "validation": "PASSED",
        }
    except Exception as exc:
        return {
            "success": False,
            "error": str(exc),
            "validation": "EXECUTION_ERROR",
        }
    finally:
        if conn:
            conn.close()


def run_sql_agent(
    question: str,
    trace_id: str | None = None,
) -> dict:
    if UNSAFE_REQUESTS.search(question):
        return {
            "success": False,
            "answer": (
                "SQL request blocked: destructive database operations "
                "are not permitted."
            ),
            "sources": [],
            "metadata": {
                "validation": "BLOCKED",
                "generated_sql": None,
                "token_usage": {"input": 0, "output": 0},
                "token_breakdown": {},
            },
        }

    sql, generation_usage = generate_sql(question, trace_id)
    result = execute_query_safely(sql)

    if not result["success"]:
        return {
            "success": False,
            "answer": f"SQL agent failure: {result['error']}",
            "sources": [],
            "metadata": {
                "validation": result["validation"],
                "generated_sql": sql,
                "token_usage": generation_usage,
                "token_breakdown": {
                    "sql_generation": generation_usage,
                },
            },
        }

    interpretation = invoke_claude(
        f"Question: {question}\n"
        f"Validated SQL: {sql}\n"
        f"Columns: {result['columns']}\n"
        f"Rows: {json.dumps(result['rows'], default=str)}\n"
        f"Results truncated: {result['truncated']}\n\n"
        "Answer only from the returned data. Mention if results were truncated.",
        max_tokens=500,
        stage="sql_interpretation",
        question=question,
        trace_id=trace_id,
    )

    interpretation_usage = {
        "input": interpretation["input_tokens"],
        "output": interpretation["output_tokens"],
    }

    usage = {
        "input": generation_usage["input"] + interpretation_usage["input"],
        "output": generation_usage["output"] + interpretation_usage["output"],
    }

    return {
        "success": True,
        "answer": interpretation["text"],
        "sources": ["RDS query result"],
        "metadata": {
            "row_count": result["row_count"],
            "truncated": result["truncated"],
            "validation": "PASSED",
            "generated_sql": sql,
            "token_usage": usage,
            "token_breakdown": {
                "sql_generation": generation_usage,
                "sql_interpretation": interpretation_usage,
            },
        },
    }
sql_tool = run_sql_agent